const body = $json.body ?? $json;
const eventId = String(body.event_id || '').trim();
const objectKey = String(body.object_key || '').trim();
const listingId = String(body.listing_id || '').trim();
const contentType = String(body.content_type || '').toLowerCase();
const byteSize = Number(body.byte_size);
if (!eventId || !objectKey || !listingId) throw new Error('Missing event_id, object_key, or listing_id');
if (!/^users\/[a-zA-Z0-9_-]+\/listings\/[a-zA-Z0-9_-]+\//.test(objectKey)) throw new Error('Invalid object key scope');
if (!['image/jpeg','image/png','image/webp'].includes(contentType)) throw new Error('Unsupported content type');
if (!Number.isSafeInteger(byteSize) || byteSize <= 0 || byteSize > 10 * 1024 * 1024) throw new Error('Invalid media size');
return [{ json: { event_id: eventId, listing_id: listingId, object_key: objectKey, content_type: contentType, byte_size: byteSize, request_id: body.request_id || eventId } }];
